 left join `hcsyria_financial_test`.`accounttype` `atype` on(`atype`.`id` = `acc`.`Accounttype_id`)) left join `hcsyria_financial_test`.`city` on(`hcsyria_financial_test`.`city`.`ID` = `sp`.`City_ID`)) left join `hcsyria_financial_test`.`project` `p` on(`p`.`ID` = `sp`.`Project_ID`)) left join `hcsyria_financial_test`.`category` `cat` on(`cat`.`ID` = `p`.`Category_ID`)) left join `hcsyria_financial_test`.`till` on(`hcsyria_financial_test`.`till`.`Account_ID` = `acc`.`ID`)) left join `hcsyria_financial_test`.`tilltypes` `tt` on(`tt`.`ID` = `hcsyria_financial_test`.`till`.`Type_ID`)) left join (select `a`.`cashaccount_id` AS `cashaccount_id`,`a`.`Till_ID` AS `Till_ID`,sum(case when `at`.`shortname` = 'I' and `tt2`.`Name` = 'SYR' then `a`.`Amount` else 0 end) AS `SYR_I`,sum(case when `at`.`shortname` in ('E','Ex') and `tt2`.`Name` = 'SYR' then `a`.`Amount` else 0 end) AS `SYR_E`,sum(case when `at`.`shortname` = 'I' and `tt2`.`Name` = 'USD' then `a`.`Amount` else 0 end) AS `USD_I`,sum(case when `at`.`shortname` in ('E','Ex') and `tt2`.`Name` = 'USD' then `a`.`Amount` else 0 end) AS `USD_E` from ((`hcsyria_financial_test`.`action` `a` left join `hcsyria_financial_test`.`actiontype` `at` on(`at`.`id` = `a`.`AType_ID`)) left join `hcsyria_financial_test`.`tilltypes` `tt2` on(`tt2`.`ID` = `a`.`currency_tilltype_id`)) group by `a`.`cashaccount_id`,`a`.`Till_ID`) `agg` on(`agg`.`cashaccount_id` = `ca`.`id` and `agg`.`Till_ID` = `hcsyria_financial_test`.`till`.`ID`)) where lcase(`tt`.`Name`) in ('syr','pay') group by `ca`.`id`,`acc`.`ID` order by `ca`.`id`
